typedef struct Node { int d; struct Node *l, *r; } Node;

Node* q[1005]; int f=0, r=-1;

void ins(Node** root, int d) {
    Node* nn=malloc(sizeof(Node)); nn->d=d; nn->l=nn->r=NULL;
    if(!*root) { *root=nn; return; }
    f=0; r=-1; q[++r]=*root;
    while(f<=r) {
        Node* curr=q[f++];
        if(!curr->l) { curr->l=nn; break; } else q[++r]=curr->l;
        if(!curr->r) { curr->r=nn; break; } else q[++r]=curr->r;
    }
}

void delDeepest(Node* root, Node* d_node) {
    f=0; r=-1; q[++r]=root;
    Node* temp;
    while(f<=r) {
        temp=q[f++];
        if(temp==d_node) { temp=NULL; free(d_node); return; }
        if(temp->r) { if(temp->r==d_node) { temp->r=NULL; free(d_node); return; } else q[++r]=temp->r; }
        if(temp->l) { if(temp->l==d_node) { temp->l=NULL; free(d_node); return; } else q[++r]=temp->l; }
    }
}

void del(Node** root, int d) {
    if(!*root) { printf("Not Found\n"); return; }
    if(!(*root)->l && !(*root)->r) {
        if((*root)->d==d) { free(*root); *root=NULL; return; }
        printf("Not Found\n"); return;
    }
    f=0; r=-1; q[++r]=*root;
    Node *curr=NULL, *key_node=NULL;
    while(f<=r) {
        curr=q[f++];
        if(curr->d==d) key_node=curr;
        if(curr->l) q[++r]=curr->l;
        if(curr->r) q[++r]=curr->r;
    }
    if(key_node) {
        key_node->d = curr->d;
        delDeepest(*root, curr);
    } else printf("Not Found\n");
}

