#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node { int d, h; struct Node *l, *r; } Node;

int max(int a, int b) { return a>b?a:b; }
int ht(Node *n) { return n?n->h:0; }
Node* nn(int d) { Node* n=malloc(sizeof(Node)); n->d=d; n->l=n->r=NULL; n->h=1; return n; }

Node* rr(Node *y) { Node *x=y->l, *T2=x->r; x->r=y; y->l=T2; y->h=max(ht(y->l), ht(y->r))+1; x->h=max(ht(x->l), ht(x->r))+1; return x; }
Node* lr(Node *x) { Node *y=x->r, *T2=y->l; y->l=x; x->r=T2; x->h=max(ht(x->l), ht(x->r))+1; y->h=max(ht(y->l), ht(y->r))+1; return y; }
int getB(Node *n) { return n?ht(n->l)-ht(n->r):0; }

Node* ins(Node* node, int d) {
    if(!node) return nn(d);
    if(d < node->d) node->l=ins(node->l, d); else if(d > node->d) node->r=ins(node->r, d); else return node;
    node->h = 1+max(ht(node->l), ht(node->r));
    int b = getB(node);
    if(b>1 && d < node->l->d) return rr(node);
    if(b<-1 && d > node->r->d) return lr(node);
    if(b>1 && d > node->l->d) { node->l=lr(node->l); return rr(node); }
    if(b<-1 && d < node->r->d) { node->r=rr(node->r); return lr(node); }
    return node;
}

